// Node.js Express Example: Enabling Gzip Compression

const express = require('express');
const compression = require('compression');
const app = express();

// 1. Simply add the middleware!
// It intercepts all responses, checks if the client sent 'Accept-Encoding: gzip',
// and if so, mathematically shrinks the JSON before it leaves the server.
app.use(compression());

app.get('/api/massive-data', (req, res) => {
  const hugeArray = new Array(10000).fill({ name: "Repetitive Data" });

  // Normally 500 KB. With compression, it becomes ~5 KB.
  res.json(hugeArray);
});
